 "content": "def transform(grid):
    """Complete a periodic stripe sequence, or a symmetric diagonal motif."""
    h, w = len(grid), len(grid[0])
    # Horizontal stripe tasks: each nonzero row is a sample of a cyclic sequence.
    row_colors = []
    stripe_grid = True
    for row in grid:
        vals = set(row)
        if len(vals) != 1:
            stripe_grid = False
            break
        row_colors.append(row[0])
    if stripe_grid:
        anchors = [i for i, c in enumerate(row_colors) if c != 0]
        period = len(anchors)
        motif = {i % period: row_colors[i] for i in anchors}
        return [[motif[r % period]] * w for r in range(h)]

    # Diagonal motif tasks: read the observed color at each distance from the
    # main diagonal, then reflect that motif periodically to fill larger offsets.
    depth = 0
    colors = {}
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                d = abs(i - j)
                colors.setdefault(d, grid[i][j])
                depth = max(depth, d)
    if depth == 0:
        return [row[:] for row in grid]
    period = 2 * depth
    out = []
    for i in range(h):
        row = []
        for j in range(w):
            d = abs(i - j) % period
            folded = min(d, period - d)
            row.append(colors[folded])
        out.append(row)
    return out
